I managed to write a custom solution to search in a .txt file and output some information but it is still quite a lot of code:

\begin{code}
public static IEnumerable<string> GetRulesFromTextFile(string txt)
    {
        string[] text = txt
            .Split(new char[] { '\r', '\n' })
            .Select(line => line.Trim())
            .Where(x => !string.IsNullOrEmpty(x))
            .ToArray();

        HashSet<string> ruleNames = new HashSet<string>();
        return text
            .Select(rule => rule.Split(':'))
            .Where(rule => rule.Length > 0 && rule[1] != "None")
            .GroupBy(rule => rule[0])
            .SelectMany(x => x
                .Select(y => $"{y}[2]")
                .Concat(y.Where(x => x != "[]")) // removing the brackets []
                .Union(new string[] { "//" + y[0].ToLower(), "none:{" + y[0] })
            .Where(y => ruleNames.Add(y)))
        .OrderBy(y => y.ToLower());
        .ToList();
    }
\end{code}

